#!/usr/bin/env node
// GENERATED by stapel-tools (stapel_tools/data/ui-wiring.mjs) — static UI wiring check.
//
// usage: node scripts/ui-wiring.mjs [--frontend <dir>] <manifest.json | dir of manifests>
//
// A manifest names, per criterion, the pages of the SPA: route, h1, testids and
// actions ({testid, handler: click|submit|change, request: {method, path}}).
// Read with the TypeScript compiler API over <frontend>/src (tests excluded):
//   route    a `path` property / attribute equal to the route (params as wildcards)
//   testid   rendered by exactly one module (data-testid literal)
//   h1       the module of the page's first testid renders <h1> or an antd Title of level 1
//   handler  the action's element carries onClick/to/href (click), onSubmit/onFinish
//            (submit) or onChange (change), or is a submit button inside such a form
//   request  the element's module, or a module it imports (two hops), holds the path
//            literal (after its /api segment) and, unless GET, the method
// It cannot see: paths assembled from concatenated literals, handlers passed in from
// a parent component through props, requests issued inside node_modules (a @stapel pair).
//
// Output: one PASS/FAIL line per check, a count line, and a final
// `UI_WIRING_RESULT <json>` line. Exit 0 green, 1 red, 2 the check could not run.
import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";

const RESULT_TAG = "UI_WIRING_RESULT";
const ERROR_TAG = "UI_WIRING_ERROR";

function fail(message) {
  console.log(`${ERROR_TAG} ${message}`);
  console.log(`${RESULT_TAG} ${JSON.stringify({ ok: false, error: message, checks: 0 })}`);
  process.exit(2);
}

function parseArgs(argv) {
  let frontend = ".";
  const rest = [];
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === "--frontend") {
      frontend = argv[i + 1] ?? "";
      i += 1;
    } else {
      rest.push(argv[i]);
    }
  }
  if (rest.length !== 1 || !frontend) {
    fail("usage: ui-wiring.mjs [--frontend <dir>] <manifest.json | dir>");
  }
  return { frontend: path.resolve(frontend), manifest: path.resolve(rest[0]) };
}

function loadTypeScript(frontend) {
  const candidates = [];
  if (process.env.UI_WIRING_TYPESCRIPT) candidates.push(process.env.UI_WIRING_TYPESCRIPT);
  candidates.push("typescript");
  const req = createRequire(path.join(frontend, "package.json"));
  for (const name of candidates) {
    try {
      return req(name);
    } catch {
      // next candidate
    }
  }
  return fail(`typescript is not installed under ${frontend} (run the frontend install first)`);
}

function loadManifests(target) {
  if (!fs.existsSync(target)) fail(`manifest not found: ${target}`);
  const files = fs.statSync(target).isDirectory()
    ? fs.readdirSync(target).filter((f) => f.endsWith(".json")).sort().map((f) => path.join(target, f))
    : [target];
  const out = [];
  for (const file of files) {
    let data;
    try {
      data = JSON.parse(fs.readFileSync(file, "utf8"));
    } catch (e) {
      fail(`manifest ${file} is not JSON: ${e.message}`);
    }
    if (!data || !Array.isArray(data.criteria)) fail(`manifest ${file} has no criteria list`);
    out.push({ file, data });
  }
  return out;
}

const SOURCE_RE = /\.(tsx?|jsx?|mjs)$/;
const TEST_RE = /(\.test\.|\.spec\.|__tests__)/;

function walk(dir, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === "node_modules" || entry.name.startsWith(".")) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, out);
    else if (SOURCE_RE.test(entry.name) && !TEST_RE.test(full)) out.push(full);
  }
  return out;
}

const PLACEHOLDER = "\u0001";

function scan(ts, file, root) {
  const text = fs.readFileSync(file, "utf8");
  const kind = file.endsWith(".tsx") || file.endsWith(".jsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS;
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, kind);
  const mod = {
    file,
    rel: path.relative(root, file).split(path.sep).join("/"),
    sf,
    testids: [],
    literals: [],
    routes: [],
    imports: [],
    methodCalls: new Set(),
    h1: false,
  };
  const lineOf = (node) => sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1;
  const literalText = (node) => {
    if (!node) return undefined;
    if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) return node.text;
    if (ts.isJsxExpression(node)) return literalText(node.expression);
    if (ts.isParenthesizedExpression(node)) return literalText(node.expression);
    return undefined;
  };
  const visit = (node) => {
    if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) {
      mod.literals.push(node.text);
    } else if (ts.isTemplateExpression(node)) {
      let s = node.head.text;
      for (const span of node.templateSpans) s += PLACEHOLDER + span.literal.text;
      mod.literals.push(s);
    }
    if ((ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) && node.moduleSpecifier
        && ts.isStringLiteral(node.moduleSpecifier)) {
      mod.imports.push(node.moduleSpecifier.text);
    }
    if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword
        && node.arguments.length && ts.isStringLiteral(node.arguments[0])) {
      mod.imports.push(node.arguments[0].text);
    }
    if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression)) {
      mod.methodCalls.add(node.expression.name.text.toLowerCase());
    }
    if (ts.isJsxAttribute(node)) {
      const name = node.name.getText(sf);
      const value = literalText(node.initializer);
      if (name === "data-testid" && value !== undefined) {
        mod.testids.push({ id: value, line: lineOf(node), element: jsxElementOf(ts, node) });
      }
      if (name === "path" && value !== undefined) mod.routes.push(value);
    }
    if (ts.isPropertyAssignment(node)) {
      const key = node.name && (ts.isIdentifier(node.name) || ts.isStringLiteral(node.name))
        ? node.name.text : "";
      const value = literalText(node.initializer);
      if (key === "path" && value !== undefined) mod.routes.push(value);
      if (key === "data-testid" && value !== undefined) {
        mod.testids.push({ id: value, line: lineOf(node), element: undefined });
      }
    }
    if (ts.isJsxOpeningElement(node) || ts.isJsxSelfClosingElement(node)) {
      const tag = node.tagName.getText(sf);
      if (tag === "h1") mod.h1 = true;
      if (tag === "Typography.Title" || tag === "Title") {
        const level = attribute(ts, node, "level");
        const levelText = level && level.initializer ? level.initializer.getText(sf) : "";
        if (!level || /^\{?\s*1\s*\}?$/.test(levelText)) mod.h1 = true;
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(sf);
  return mod;
}

function jsxElementOf(ts, attributeNode) {
  let node = attributeNode.parent;
  while (node && !ts.isJsxOpeningElement(node) && !ts.isJsxSelfClosingElement(node)) node = node.parent;
  return node;
}

function attribute(ts, element, name) {
  if (!element || !element.attributes) return undefined;
  return element.attributes.properties.find(
    (p) => ts.isJsxAttribute(p) && p.name.getText() === name,
  );
}

function attributeValue(ts, element, name) {
  const attr = attribute(ts, element, name);
  if (!attr || !attr.initializer) return undefined;
  if (ts.isStringLiteral(attr.initializer)) return attr.initializer.text;
  const expr = attr.initializer.expression;
  if (expr && (ts.isStringLiteral(expr) || ts.isNoSubstitutionTemplateLiteral(expr))) return expr.text;
  return undefined;
}

const HANDLERS = {
  click: ["onClick", "to", "href", "onPress"],
  submit: ["onSubmit", "onFinish"],
  change: ["onChange", "onSelect"],
};
const FORM_HANDLERS = ["onSubmit", "onFinish"];

function enclosingForm(ts, element) {
  let node = element.parent;
  while (node) {
    if (ts.isJsxElement(node)) {
      const opening = node.openingElement;
      const tag = opening.tagName.getText();
      if ((tag === "form" || tag === "Form") && FORM_HANDLERS.some((h) => attribute(ts, opening, h))) {
        return opening;
      }
    }
    node = node.parent;
  }
  return undefined;
}

function handlerOf(ts, element, kind) {
  const names = HANDLERS[kind] ?? HANDLERS.click;
  const own = names.find((h) => attribute(ts, element, h));
  if (own) return own;
  const isSubmit = ["submit"].includes(attributeValue(ts, element, "type") ?? "")
    || ["submit"].includes(attributeValue(ts, element, "htmlType") ?? "");
  if ((kind === "click" && isSubmit) || kind === "submit") {
    const form = enclosingForm(ts, element);
    if (form) return `${form.tagName.getText()} ${FORM_HANDLERS.find((h) => attribute(ts, form, h))}`;
  }
  return undefined;
}

function resolveImport(fromFile, spec, known) {
  if (!spec.startsWith(".")) return undefined;
  const base = path.resolve(path.dirname(fromFile), spec);
  const stem = base.replace(/\.(m?js|jsx|tsx?)$/, "");
  const tries = [base, `${stem}.ts`, `${stem}.tsx`, `${stem}.js`, `${stem}.jsx`, `${stem}.mjs`,
    path.join(base, "index.ts"), path.join(base, "index.tsx"), path.join(base, "index.js")];
  return tries.find((t) => known.has(t));
}

function reachable(mod, byFile, hops) {
  const seen = new Map([[mod.file, mod]]);
  let frontier = [mod];
  for (let i = 0; i < hops; i += 1) {
    const next = [];
    for (const m of frontier) {
      for (const spec of m.imports) {
        const target = resolveImport(m.file, spec, byFile);
        if (target && !seen.has(target)) {
          seen.set(target, byFile.get(target));
          next.push(byFile.get(target));
        }
      }
    }
    frontier = next;
  }
  return [...seen.values()];
}

function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const PARAM_RE = /(<[^>/]+>|\{[^}/]+\}|:[A-Za-z_][\w]*)/g;

function requestNeedle(requestPath) {
  const p = String(requestPath || "").split("?")[0];
  const at = p.indexOf("/api/");
  const tail = at >= 0 ? p.slice(at + 4) : p;
  const body = tail.replace(/\/+$/, "");
  const pattern = body.split(PARAM_RE).map((part, i) => (i % 2 ? `[^/]+` : escapeRe(part))).join("");
  return { tail, re: new RegExp(`${pattern}/?(?:$|\\?|${PLACEHOLDER})`) };
}

function holdsRequest(mod, needle, method) {
  const hasPath = mod.literals.some((s) => needle.re.test(s));
  if (!hasPath) return false;
  const m = String(method || "GET").toUpperCase();
  if (m === "GET") return true;
  return mod.literals.some((s) => s.toUpperCase() === m) || mod.methodCalls.has(m.toLowerCase());
}

const PARAM_SEGMENT_RE = /^(<[^>/]+>|\{[^}/]+\}|:[A-Za-z_][\w]*\??)$/;

function routePattern(route) {
  const parts = String(route).replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
  return parts.map((seg) => (PARAM_SEGMENT_RE.test(seg) ? null : seg));
}

function routeDeclared(route, mods) {
  const want = routePattern(route);
  const matches = (literal) => {
    const got = routePattern(literal);
    if (!got.length && want.length) return false;
    if (got.length > want.length) return false;
    if (!got.length && !want.length) return true;
    const tail = want.slice(want.length - got.length);
    return tail.every((seg, i) => (seg === null ? got[i] === null : seg === got[i]));
  };
  for (const mod of mods) {
    if (mod.routes.some((r) => (r === "/" || r === "") ? want.length === 0 : matches(r))) return mod;
  }
  return undefined;
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const ts = loadTypeScript(args.frontend);
  const manifests = loadManifests(args.manifest);
  const src = path.join(args.frontend, "src");
  const files = walk(src);
  if (!files.length) fail(`no source files under ${src}`);
  const mods = files.map((f) => scan(ts, f, args.frontend));
  const byFile = new Map(mods.map((m) => [m.file, m]));

  const results = [];
  const criteria = {};
  let testidCount = 0;
  let actionCount = 0;
  const record = (task, cid, route, check, ok, detail) => {
    const key = task ? `${task}:${cid}` : cid;
    criteria[key] ??= { task, id: cid, ok: true, failed: [] };
    const line = `${ok ? "PASS" : "FAIL"} ${cid} ${route} ${check}: ${detail}`;
    if (!ok) {
      criteria[key].ok = false;
      criteria[key].failed.push(`${route} ${check}: ${detail}`);
    }
    results.push({ ok, line });
  };

  for (const { data } of manifests) {
    const task = data.task ?? "";
    for (const criterion of data.criteria) {
      const cid = String(criterion.id ?? "?");
      for (const page of criterion.pages ?? []) {
        const route = String(page.route ?? "?");
        if (page.route !== undefined) {
          const where = routeDeclared(page.route, mods);
          record(task, cid, route, "route", Boolean(where),
            where ? `declared in ${where.rel}` : "no route object or <Route> declares this path");
        }
        const homes = {};
        for (const id of page.testids ?? []) {
          testidCount += 1;
          const owners = mods.filter((m) => m.testids.some((t) => t.id === id));
          if (owners.length === 1) {
            const at = owners[0].testids.find((t) => t.id === id);
            homes[id] = { mod: owners[0], at };
            record(task, cid, route, `testid ${id}`, true, `${owners[0].rel}:${at.line}`);
          } else if (!owners.length) {
            record(task, cid, route, `testid ${id}`, false, "rendered by no module under src/");
          } else {
            record(task, cid, route, `testid ${id}`, false,
              `ambiguous, in ${owners.length} modules: ${owners.map((m) => m.rel).join(", ")}`);
          }
        }
        if (page.h1) {
          const first = (page.testids ?? [])[0];
          const home = first ? homes[first] : undefined;
          if (!home) {
            record(task, cid, route, "h1", false, "no page module (its first testid is not rendered)");
          } else {
            record(task, cid, route, "h1", home.mod.h1,
              home.mod.h1 ? `${home.mod.rel}` : `${home.mod.rel} renders no <h1> or level-1 Title`);
          }
        }
        for (const action of page.actions ?? []) {
          actionCount += 1;
          const id = String(action.testid ?? "?");
          const kind = String(action.handler ?? "click");
          const owners = mods.filter((m) => m.testids.some((t) => t.id === id));
          if (owners.length !== 1) {
            record(task, cid, route, `action ${id}`, false,
              owners.length ? `testid in ${owners.length} modules` : "testid rendered by no module under src/");
            continue;
          }
          const mod = owners[0];
          const at = mod.testids.find((t) => t.id === id);
          const tag = at.element ? at.element.tagName.getText(mod.sf) : "element";
          const handler = at.element ? handlerOf(ts, at.element, kind) : undefined;
          record(task, cid, route, `action ${id} ${kind}`, Boolean(handler),
            handler ? `<${tag}> ${handler} at ${mod.rel}:${at.line}`
              : `<${tag}> at ${mod.rel}:${at.line} has no ${kind} handler (${(HANDLERS[kind] ?? HANDLERS.click).join(", ")})`
                + (kind === "click" ? " and is not a submit button inside a <form onSubmit>" : ""));
          if (action.request) {
            const method = String(action.request.method ?? "GET").toUpperCase();
            const needle = requestNeedle(action.request.path);
            const scope = reachable(mod, byFile, 2);
            const holder = scope.find((m) => holdsRequest(m, needle, method));
            record(task, cid, route, `action ${id} request`, Boolean(holder),
              holder ? `${method} ${needle.tail} in ${holder.rel}`
                : `no ${method} ${needle.tail} in ${mod.rel} or the modules it imports `
                  + `(${scope.filter((m) => m !== mod).map((m) => m.rel).join(", ") || "none"})`);
          }
        }
      }
    }
  }
  if (!results.length) fail("the manifest names no route, testid, h1 or action: checked 0");
  for (const r of results) console.log(r.line);
  const failed = results.filter((r) => !r.ok).length;
  console.log(`ui-wiring: ${results.length} checks, ${failed} failed `
    + `(${testidCount} testids, ${actionCount} actions, ${mods.length} modules scanned)`);
  const ok = failed === 0;
  console.log(`${RESULT_TAG} ${JSON.stringify({ ok, checks: results.length, failed, criteria: Object.values(criteria) })}`);
  process.exit(ok ? 0 : 1);
}

main();
